import java.util.*;
import java.io.*;

public class Div680 {
    static int n, mod, offset;
    static int[][][] dp;

    static int computeDP(int done, int idx, int diff) {
        if (idx == n) return diff > 0 ? 1 : 0;
        int key = diff + offset;
        if (dp[done][idx][key] != -1) return dp[done][idx][key];
        int remaining = n - idx;
        int result = 0;
        for (int left = 0; left < remaining; left++) {
            int rightStart = (done == 1) ? 0 : left;
            for (int right = rightStart; right < remaining; right++) {
                result = (result + computeDP(done | ((left < right) ? 1 : 0), idx + 1, diff + left - right)) % mod;
            }
        }
        return dp[done][idx][key] = result;
    }

    static long computeCount(int pos) {
        if (pos == n - 1) return 0L;
        long total = (long)(n - pos) * computeCount(pos + 1) % mod;
        for (int left = 0; left < n - pos; left++) {
            for (int right = left + 1; right < n - pos; right++) {
                total = (total + computeDP(1, pos + 1, left - right)) % mod;
            }
        }
        return total;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        String[] line = reader.readLine().split("\\s+");
        n = Integer.parseInt(line[0]);
        mod = Integer.parseInt(line[1]);
        offset = n * (n - 1);
        dp = new int[2][n][2 * offset + 1];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < n; j++) {
                Arrays.fill(dp[i][j], -1);
            }
        }
        writer.println(computeCount(0));
        writer.flush();
        writer.close();
        reader.close();
    }

    static long gcd(long a, long b) {
        while (a != 0) {
            long temp = a;
            a = b % a;
            b = temp;
        }
        return b;
    }

    static class Scanner {
        private BufferedReader br;
        private StringTokenizer st;

        public Scanner(InputStream input) { br = new BufferedReader(new InputStreamReader(input)); }
        public Scanner(FileReader fr) { br = new BufferedReader(fr); }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public int nextInt() throws IOException { return Integer.parseInt(next()); }
        public long nextLong() throws IOException { return Long.parseLong(next()); }
        public String nextLine() throws IOException { return br.readLine(); }

        public double nextDouble() throws IOException {
            String s = next();
            boolean negative = s.charAt(0) == '-';
            if (negative) s = s.substring(1);
            double value = 0, factor = 1;
            boolean decimal = false;
            for (char c : s.toCharArray()) {
                if (c == '.') { decimal = true; continue; }
                value = value * 10 + (c - '0');
                if (decimal) factor *= 10;
            }
            return (value / factor) * (negative ? -1 : 1);
        }

        public boolean ready() throws IOException { return br.ready(); }
    }
}
